@@ -74,7 +74,7 @@
  *   nl:aff:<id>:payouts  hash  payout id -> what the creator says they paid
  */
 import { rememberAffiliate } from "@/lib/affiliate-hub";
-import { type Paid, paypalPaymentId, readPayPalRefunds, refundedKey as paypalRefundedKey } from "@/lib/paypal-sales";
+import { type Paid, paypalPaymentId, readPayPalRefundsWithCoverage, refundedKey as paypalRefundedKey } from "@/lib/paypal-sales";
 import { MAX_STORE_BYTES, saleHandles, storeForEmailSeen, storeForId, storeRef } from "@/lib/store";
 import { createHash, randomBytes } from "node:crypto";
 import { EMAIL_PATTERN, MAX_EMAIL_LENGTH, normaliseEmail } from "@/lib/auth";
@@ -2334,7 +2334,7 @@ export async function notePartners(
  * the share it had when the buyer paid, and to every partner who shares in
  * the product. Once per order, whichever of the return page and the sweep
  * hands it over first. A refund in full on PayPal takes it back in the book
- * (readBook, through readPayPalRefunds).
+ * (readBook, through readPayPalRefundsWithCoverage).
  */
 export async function creditPayPalSale(store: Store, paid: Paid, title: string): Promise<void> {
   if (!store.statsId || !isRedisConfigured()) return;
@@ -2928,14 +2928,24 @@ export async function readBook(store: Store, only?: string, limits: { deadline?:
       refunds = read.byIntent;
       refundsChecked = read.complete;
       // PayPal's refunds in full, named by the payment as the book names it. One with no capture id never meets its
-      // sale, and one in another currency than its sale's means nothing in its cents: either leaves what is owed
-      // unknown (refundsChecked), never a refund of nothing, so no payout is made on it (rule 24, as #3189 for
-      // Stripe). A refund is in full, so the same payment listed twice counts once.
-      const paypalCurrency = new Map(everything.filter((r) => r.pi.startsWith("paypal:")).map((r) => [r.pi, r.currency.toLowerCase()] as const));
+      // sale, one in another currency than its sale's means nothing in its cents, and one whose cents are not a
+      // whole positive amount, or not its sale's whole amount (a PayPal refund here is in full), would count as a
+      // refund of less: each leaves what is owed unknown (refundsChecked), never a refund of nothing, so no payout
+      // is made on it (rule 24, as #3189 for Stripe). So does a reading that did not cover every refund since the
+      // oldest line (more listed than PAYPAL_REFUNDS_READ, or a listed one whose record is gone): a refund past the
+      // cut is never paid on. A refund is in full, so the same payment listed twice counts once.
+      const paypalSales = new Map<string, { currency: string; total: number }[]>();
+      for (const r of everything) {
+        if (r.pi.startsWith("paypal:")) paypalSales.set(r.pi, [...(paypalSales.get(r.pi) ?? []), { currency: r.currency.toLowerCase(), total: r.total }]);
+      }
       const paypalSeen = new Set<string>();
-      for (const r of await readPayPalRefunds(store.statsId, since)) {
-        const sale = typeof r.capture === "string" && r.capture ? paypalCurrency.get(paypalPaymentId(r.capture)) : null;
-        if (sale === null || typeof r.currency !== "string" || (sale !== undefined && sale !== r.currency.toLowerCase())) refundsChecked = false;
+      const paypal = await readPayPalRefundsWithCoverage(store.statsId, since);
+      if (paypal.partial) refundsChecked = false;
+      for (const r of paypal.rows) {
+        const named = typeof r.capture === "string" && r.capture !== "";
+        const sales = named ? paypalSales.get(paypalPaymentId(r.capture)) : undefined;
+        const readable = named && typeof r.currency === "string" && Number.isSafeInteger(r.cents) && r.cents > 0;
+        if (!readable || (sales ?? []).some((sale) => sale.currency !== r.currency.toLowerCase() || sale.total !== r.cents)) refundsChecked = false;
         else if (!paypalSeen.has(r.capture)) {
           paypalSeen.add(r.capture);
           refunds.set(paypalPaymentId(r.capture), (refunds.get(paypalPaymentId(r.capture)) ?? 0) + r.cents);
diff --git a/tests/affiliate-paypal-refunds-exact.test.ts b/tests/affiliate-paypal-refunds-exact.test.ts
index 98c22036..2376315b 100644
--- a/tests/affiliate-paypal-refunds-exact.test.ts
+++ b/tests/affiliate-paypal-refunds-exact.test.ts
@@ -7,13 +7,17 @@
  * guard; a refund in another currency than its sale's was added to the
  * sale's cents as if it were the same money. Both now leave the book's
  * refunds unchecked, so nothing is paid on them, as the Stripe side does
- * (#3189). The same payment listed twice counts once. An amount or currency
- * that does not read is the reader's (claude4/paypal-cents-exact), not here.
+ * (#3189). The same payment listed twice counts once. A refund whose cents
+ * are not the sale's whole positive amount (0, negative, a part, not a whole
+ * number, missing) is unknown too, never a refund of less. A reading that
+ * did not cover every refund since the oldest line (more than
+ * PAYPAL_REFUNDS_READ listed, or a listed refund whose record is gone)
+ * leaves the book unchecked, so a refund past the cut is never paid on.
  * Synthetic only: the Redis stub, no provider call.
  */
 import { creditPayPalSale, readBook } from "@/lib/affiliates";
 import { NO_AFFILIATES } from "@/lib/affiliate-setting";
-import type { Paid } from "@/lib/paypal-sales";
+import { PAYPAL_REFUNDS_READ, type Paid } from "@/lib/paypal-sales";
 import { payableLines } from "@/lib/paypal-payouts";
 import type { Store } from "@/lib/store";
 import { store as redis } from "./redis-stub";
@@ -111,6 +115,44 @@ async function main(): Promise<void> {
   await held("A capture that is not text", { ...paid, capture: 12345 });
   await held("A refund in another currency than the sale's", { ...paid, currency: "eur" });

+  await held("A refund of no cents", { ...paid, cents: 0 });
+  await held("A refund of negative cents", { ...paid, cents: -5000 });
+  await held("A refund of a part of the sale", { ...paid, cents: 100 });
+  await held("A refund in cents that are not a whole number", { ...paid, cents: 4999.5 });
+  await held("A refund in cents that are not a number", { ...paid, cents: "abc" });
+  await held("A refund with no cents", { ...paid, cents: undefined });
+
+  part("A listed refund whose kept record is gone: the read is partial, nothing is paid");
+  await setup(null, true);
+  const gone = await offered();
+  is("the book is not checked", gone.checked, false);
+  is("nothing passes the refund guard", gone.through, 0);
+
+  // `others` refunds of other sales, each with its record, listed before this sale's own refund.
+  const crowd = async (others: number): Promise<void> => {
+    await setup(paid, true);
+    const commands: (string | number)[][] = [];
+    for (let i = 0; i < others; i += 1) {
+      const order = `7O${String(i).padStart(15, "0")}`;
+      commands.push(["SET", `nl:ppsell:paid:${order}`, JSON.stringify({ ...paid, order, capture: `5C${String(i).padStart(14, "0")}`, via: undefined })]);
+      commands.push(["ZADD", `nl:ppsell:refunded:${SID}`, String(AT - 1800), order]);
+    }
+    await redis.pipeline(commands);
+  };
+
+  part(`Control: ${PAYPAL_REFUNDS_READ} refunds in all, this sale's the last: read whole, its commission taken back`);
+  await crowd(PAYPAL_REFUNDS_READ - 1);
+  const whole = await offered();
+  is("checked", whole.checked, true);
+  is("no commission", whole.commission, 0);
+  is("nothing offered", whole.through, 0);
+
+  part(`More than ${PAYPAL_REFUNDS_READ} refunds, this sale's past the cut: the read is partial, nothing is paid`);
+  await crowd(PAYPAL_REFUNDS_READ);
+  const cut = await offered();
+  is("the book is not checked", cut.checked, false);
+  is("nothing passes the refund guard", cut.through, 0);
+
   part("The same refund listed twice counts once, and the book stays checked");
   await setup(paid, true);
   const twice = await withRange([ORDER, String(AT), ORDER, String(AT)], () => readBook(store));
